#!/usr/bin/env bash
# The evidence directory is read-only input. Every generated byte goes to a fresh WORK.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
if [[ $# -lt 1 || $# -gt 2 ]]; then echo "Usage: bash $0 /new/work/directory [/path/to/sparse/src/main/java]" >&2; exit 2; fi
WORK="$1"
if [[ -e "$WORK" ]]; then echo "Refusing existing work directory: $WORK" >&2; exit 2; fi
REPO="${REPO:-/workspace/shared/nagaport-player-sound-cp59}"
JAVA_HOME="${JAVA_HOME:-/workspace/shared/nagaport-toolchain/java8}"
BASE=641d2641bf196265e34e3f6968dba795f1dd061b
OVERLAY="${2:-$REPO/ntm-port-1.12.2/src/main/java}"
mkdir -p "$WORK/compiler/classes" "$WORK/compiler/empty-sourcepath"
WORK="$(cd "$WORK" && pwd)"
SCRATCH="$WORK/compiler"
for FILE in WorldSoundWideningAttribution.java WorldEffectAllowlist.java select_widening.py verify_after.py native-classpath.txt; do cp "$HERE/$FILE" "$WORK/$FILE"; done
git -C "$REPO" archive --format=zip -o "$SCRATCH/baseline-sources.zip" "$BASE" ntm-port-1.12.2/src/main/java
git -C "$REPO" show "$BASE":ntm-port-1.12.2/src/main/java/com/hbm/main/ModSoundEvents.java > "$WORK/ModSoundEvents.baseline.java.txt"
git -C "$REPO" show "$BASE":ntm-port-1.12.2/porting/tests/native-world-sound/source-manifest.json > "$WORK/existing-world-sound-manifest.json"
cmp "$HERE/ModSoundEvents.baseline.java.txt" "$WORK/ModSoundEvents.baseline.java.txt"
cmp "$HERE/existing-world-sound-manifest.json" "$WORK/existing-world-sound-manifest.json"
python3 - "$HERE/inputs.json" "$WORK" <<'PY'
from pathlib import Path
import hashlib,json,sys
inputs=json.loads(Path(sys.argv[1]).read_text());work=Path(sys.argv[2]);archive=work/'compiler/baseline-sources.zip';assert hashlib.sha256(archive.read_bytes()).hexdigest()==inputs['archive_sha256'];inputs['archive']=str(archive);(work/'inputs.json').write_text(json.dumps(inputs,indent=2)+'\n')
PY
"$JAVA_HOME/bin/javac" -cp "$JAVA_HOME/lib/tools.jar" -d "$SCRATCH/classes" "$WORK/WorldSoundWideningAttribution.java" "$WORK/WorldEffectAllowlist.java"
JAVA=("$JAVA_HOME/bin/java" -Xmx5g -cp "$SCRATCH/classes:$JAVA_HOME/lib/tools.jar")
"${JAVA[@]}" WorldEffectAllowlist "$WORK/ModSoundEvents.baseline.java.txt" > "$WORK/existing-registry-ast.tsv"
"${JAVA[@]}" WorldSoundWideningAttribution "$SCRATCH/baseline-sources.zip" "$WORK/native-classpath.txt" - "$WORK/before-all-diagnostics.tsv" - > "$WORK/before-all.tsv" 2> "$WORK/before.log"
python3 "$WORK/select_widening.py" > "$WORK/before-verification.log"
"${JAVA[@]}" WorldSoundWideningAttribution "$SCRATCH/baseline-sources.zip" "$WORK/native-classpath.txt" "$WORK/selected-sites.tsv" "$WORK/after-all-diagnostics.tsv" "$OVERLAY" > "$WORK/after.tsv" 2> "$WORK/after.log"
python3 "$WORK/verify_after.py" "$OVERLAY" > "$WORK/after-verification.log"
cat "$WORK/before.log" "$WORK/before-verification.log" "$WORK/after.log" "$WORK/after-verification.log"
echo "Fresh replay output: $WORK"
